import{recoverAtLastHub}from'../../../economy/actions.mjs';
import{stableJSON}from'../../../compatibility/codec.mjs';
const same=(a,b)=>stableJSON(a)===stableJSON(b);
// Only invoked inside owner persist staging. A plain result is NOT a receipt or reward authority.
// Fixed S5 visual landing awaits separate root centre selection; no caller landing accepted.
export function selectedS5Recovery({world,before,next,supports}){const r=next.economy?.recovery,old=before.economy?.recovery;if(!r||same(r,old)||r.status!=='RETURNED_VERIFIED_HOST')return null;if(next.sessionId!==before.sessionId||next.economy.battleSerial!==before.economy.battleSerial+1||r.battleId!==`${next.sessionId}:${next.economy.battleSerial}`)throw Error('RECOVERY_BATTLE_PROVENANCE_MISMATCH');const probe=structuredClone(next);recoverAtLastHub(probe,world.catalog,world.host,r.battleId);if(!same(probe.position,next.position)||!same(probe.party,next.party)||!same(probe.economy.recovery,r))throw Error('ORIGINAL_RECOVERY_DESTINATION_MISMATCH');if(r.hubId!=='CENTER:S5')throw Object.assign(Error('S5_RECOVERY_DESTINATION_HOLD'),{code:'S5_RECOVERY_DESTINATION_HOLD'});const hub=world.host.hubs['CENTER:S5'];if(!hub||!same(hub.position,next.position)||!next.world.visitedHubs.includes('CENTER:S5'))throw Error('RECOVERY_CANONICAL_LANDING_MISMATCH');if(typeof supports!=='function'||supports([380,630])!==true)throw Error('S5_RECOVERY_NATIVE_SUPPORT');return{hubId:r.hubId,battleId:r.battleId,hubOrigin:'original-center-recovery',hubPose:{foot:[380,630],facing:'down'},canonicalPosition:structuredClone(next.position)}}
